package com.loyu3c.rental;
import org.json.*;import java.time.YearMonth;import org.junit.Test;import static org.junit.Assert.*;
public class OwnerReportTest {
    private JSONObject base()throws Exception{return new JSONObject().put("properties",new JSONArray().put(new JSONObject().put("id","a").put("name","A棟")).put(new JSONObject().put("id","b").put("name","B棟"))).put("units",new JSONArray().put(new JSONObject().put("id","u").put("propertyId","a"))).put("leases",new JSONArray().put(new JSONObject().put("id","l").put("unitId","u").put("tenant","王小明").put("unitCodeSnapshot","R1").put("start","2026-01-01").put("end","2027-01-01"))).put("invoices",new JSONArray().put(new JSONObject().put("id","i").put("leaseId","l").put("month","2026-10").put("rent",10000).put("water",0).put("electricity",0))).put("receipts",new JSONArray()).put("deposits",new JSONArray()).put("expenses",new JSONArray()).put("settlements",new JSONArray());}
    private JSONObject receipt(String date,long amount,boolean cash)throws Exception{return new JSONObject().put("leaseId","l").put("date",date).put("cash",cash).put("amount",amount).put("allocations",new JSONArray().put(new JSONObject().put("invoiceId","i").put("amount",amount)));}
    @Test public void paidUsesCutoffAndPrepaymentsAreNotCurrentMonthCash()throws Exception{JSONObject b=base();b.getJSONArray("receipts").put(receipt("2026-09-20",2000,true)).put(receipt("2026-10-05",3000,true)).put(receipt("2026-11-05",5000,true));JSONObject t=OwnerReport.build(b,YearMonth.of(2026,10)).getJSONObject("total");assertEquals(5000,t.getLong("paid"));assertEquals(5000,t.getLong("remaining"));assertEquals(3000,t.getLong("cash"));}
    @Test public void offsetsDepositsAndTopupsDoNotDoubleCountCash()throws Exception{JSONObject b=base();b.getJSONArray("receipts").put(receipt("2026-10-10",4000,false)).put(receipt("2026-10-11",2000,false));b.getJSONArray("deposits").put(new JSONObject().put("leaseId","l").put("date","2026-09-01").put("kind","收到押金").put("amount",10000)).put(new JSONObject().put("leaseId","l").put("date","2026-10-10").put("kind","押金抵付費用").put("amount",4000)).put(new JSONObject().put("leaseId","l").put("date","2026-11-01").put("kind","退還押金").put("amount",6000));b.getJSONArray("settlements").put(new JSONObject().put("leaseId","l").put("payments",new JSONArray().put(new JSONObject().put("date","2026-10-11").put("amount",3000))));JSONObject t=OwnerReport.build(b,YearMonth.of(2026,10)).getJSONObject("total");assertEquals(6000,t.getLong("paid"));assertEquals(0,t.getLong("cash"));assertEquals(3000,t.getLong("topups"));assertEquals(3000,t.getLong("net"));assertEquals(6000,t.getLong("held"));}
    @Test public void splitExpensesExcludeVoidsAndEmptyBillsAreNotPaid()throws Exception{JSONObject b=base();b.put("invoices",new JSONArray());JSONObject expense=new JSONObject().put("date","2026-10-02").put("splits",new JSONArray().put(new JSONObject().put("propertyId","a").put("amount",1000)).put(new JSONObject().put("propertyId","b").put("amount",2000)));b.getJSONArray("expenses").put(expense).put(new JSONObject(expense.toString()).put("void",true));JSONObject r=OwnerReport.build(b,YearMonth.of(2026,10));assertEquals(3000,r.getJSONObject("total").getLong("expenses"));assertEquals(1000,r.getJSONArray("properties").getJSONObject(0).getLong("expenses"));assertEquals("本月未建帳單",r.getJSONArray("tenants").getJSONObject(0).getString("status"));}
    @Test public void csvQuotesNamesProtectsFormulasAndDoesNotExposeContacts()throws Exception{JSONObject b=base();b.getJSONArray("leases").getJSONObject(0).put("tenant","=SUM(1,2)").put("phone","0912345678").put("email","private@gmail.com");String csv=OwnerReport.csv(OwnerReport.build(b,YearMonth.of(2026,10)));assertTrue(csv.startsWith("\uFEFF"));assertTrue(csv.contains("\"'=SUM(1,2)\""));assertFalse(csv.contains("0912345678"));assertFalse(csv.contains("private@gmail.com"));}
}
